const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Rosetta branch of Nile Delta (31.2°N, 30.4°E)
  const geometry = ee.Geometry.Point([30.4, 31.2]).buffer(5000);

  // 1984: Landsat 5 TM
  const col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('1984-01-01', '1984-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size1984 = col1984.size().getInfo();
  console.log(`1984 Images: ${size1984}`);

  if (size1984 === 0) {
    console.log('No Landsat 5 data for 1984.');
    console.log('C1');
    return;
  }

  // 2021: Landsat 8
  const col2021 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate('2021-01-01', '2021-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size2021 = col2021.size().getInfo();
  console.log(`2021 Images: ${size2021}`);

  if (size2021 === 0) {
    console.log('No Landsat 9 data for 2021.');
    console.log('C1');
    return;
  }

  // Calculate NDVI for 1984
  const ndvi1984 = col1984.map(img => {
    const sr = img.select(['SR_B3', 'SR_B4']); // Red, NIR for Landsat 5
    const ndvi = sr.normalizedDifference(['SR_B4', 'SR_B3']);
    return ndvi;
  }).mean();

  const count1984 = ndvi1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('nd').getInfo();

  const mean1984 = ndvi1984.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('nd').getInfo();

  console.log(`1984 NDVI: ${mean1984 !== null ? mean1984.toFixed(3) : 'null'}, Pixels: ${count1984}`);

  if (count1984 === 0) {
    console.log('No valid pixels for 1984 after masking.');
    console.log('C2');
    return;
  }

  // Calculate NDVI for 2021
  const ndvi2021 = col2021.map(img => {
    const sr = img.select(['SR_B4', 'SR_B5']); // Red, NIR for Landsat 8/9
    const ndvi = sr.normalizedDifference(['SR_B5', 'SR_B4']);
    return ndvi;
  }).mean();

  const count2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('nd').getInfo();

  const mean2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('nd').getInfo();

  console.log(`2021 NDVI: ${mean2021 !== null ? mean2021.toFixed(3) : 'null'}, Pixels: ${count2021}`);

  if (count2021 === 0) {
    console.log('No valid pixels for 2021 after masking.');
    console.log('C2');
    return;
  }

  // Validation & Comparison
  if (mean1984 === null || mean2021 === null || isNaN(mean1984) || isNaN(mean2021)) {
    console.log('Calculation failed: null or NaN values.');
    console.log('C3');
    return;
  }

  if (mean1984 < -1 || mean1984 > 1 || mean2021 < -1 || mean2021 > 1) {
    console.log('Invalid NDVI range detected.');
    console.log('C3');
    return;
  }

  console.log(`Comparison: 1984 NDVI (${mean1984.toFixed(3)}) vs 2021 NDVI (${mean2021.toFixed(3)})`);

  if (mean1984 > mean2021) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
